import type {ReactNode} from 'react';
import type {BrowseFilters,WatchSequence} from '../journey';
import type {CatalogView,Work} from '../types';
export type PageSize=24|48;
export type ConditionKey='search'|'group'|'generation'|'queue'|'stageFilter'|'watch'|'sort';
export type ActiveCondition={key:ConditionKey;label:string;value:string};
export type PageModel={page:number;pageSize:PageSize;pageCount:number;total:number;start:number;end:number};
export type LibraryModel={orderedWorks:Work[];orderedIds:string[];rows:Work[];pagination:PageModel;facetCounts:{queue:Record<string,number>;stage:Record<string,number>};activeConditions:ActiveCondition[];watchableIds:string[]};
export type RestoreTarget={anchorId?:string;offset?:number;page?:number;legacyLimit?:number;focusId?:string;requestKey?:string|number};
export type RestoreResolution={page:number;anchorId:string|null;offset:number;focus:'anchor'|'search';reason:'anchor'|'missing-anchor'|'page'};
export type ResultsViewProps={model:LibraryModel;page:number;pageSize:PageSize;onPageChange:(page:number,pageSize:PageSize)=>void;renderWork:(work:Work,onOpen:()=>void)=>ReactNode;onOpenWork:(workId:string,sequence:WatchSequence)=>void;sequence:WatchSequence;restoreTarget?:RestoreTarget;restoreReady?:boolean;onRestoreReady?:(resolution:RestoreResolution)=>void;loading?:boolean;error?:string|null;searchId?:string};
export type SequenceStatus='available'|'missing'|'unavailable'|'filtered'|'member-unlinked';
export type SequenceRow={id:string;position:number;name:string;status:SequenceStatus;current:boolean;next:boolean};
export type SequenceModel={rows:SequenceRow[];total:number;currentPosition:number|null;nextId:string|null;continuableCount:number;unrecoverable:boolean};
export type SequencePreviewProps={sequence:WatchSequence;currentId:string;catalog:CatalogView;onNext?:()=>void;nextDisabled?:boolean};

import type {PageModel,PageSize,RestoreResolution,RestoreTarget} from './contract';
/** Public callers may hydrate untrusted navigation numbers. Legacy limits are never page numbers. */
export function paginate(total:number,page=1,pageSize:PageSize=24):PageModel{
 const size:PageSize=pageSize===48?48:24;
 const count=Number.isFinite(total)?Math.max(0,Math.floor(total)):0;
 const pageCount=Math.max(1,Math.ceil(count/size));
 const current=Math.min(pageCount,Math.max(1,Number.isFinite(page)?Math.floor(page):1));
 return {page:current,pageSize:size,pageCount,total:count,start:count?(current-1)*size+1:0,end:Math.min(current*size,count)};
}
export function resolveRestoreTarget(orderedIds:readonly string[],pageSize:PageSize,target:RestoreTarget={}):RestoreResolution{
 // Historical hosts saved DOM anchors as work-<id>. Prefer an exact ID first.
 let index=target.anchorId?orderedIds.indexOf(target.anchorId):-1;
 if(index<0&&target.anchorId?.startsWith('work-'))index=orderedIds.indexOf(target.anchorId.slice(5));
 const offset=Number.isFinite(target.offset)?target.offset!:0;
 if(index>=0)return {page:paginate(orderedIds.length,Math.floor(index/(pageSize===48?48:24))+1,pageSize).page,anchorId:orderedIds[index],offset,focus:'anchor',reason:'anchor'};
 return {page:paginate(orderedIds.length,target.page??1,pageSize).page,anchorId:null,offset:0,focus:'search',reason:target.anchorId?'missing-anchor':'page'};
}

import type {BrowseFilters} from '../journey';
import type {CatalogView} from '../types';
import {indexWorkNames,matchingWorks,sortWorks} from '../watch-sequence';
import {queueLabels} from '../queues';
import {stageMatches} from '../stage-display';
import {paginate} from './paging-model';
import type {ActiveCondition,ConditionKey,LibraryModel,PageSize} from './contract';
const defaults:Record<ConditionKey,string>={search:'',group:'all',generation:'all',queue:'all',stageFilter:'all',watch:'all',sort:'default'};
const labels:Record<ConditionKey,string>={search:'名称',group:'团体',generation:'世代',queue:'队列',stageFilter:'舞台',watch:'观看状态',sort:'排序'};
const stageLabels:Record<string,string>={all:'全部',ready:'有舞台',alternative:'其他现场',pending:'暂无舞台'};
const watchLabels:Record<string,string>={watched:'已观看',unwatched:'未观看',unmarked:'未标记'};
const sortLabels:Record<string,string>={'release-desc':'发行时间：新到旧','release-asc':'发行时间：旧到新','score-desc':'评分：高到低'};
/** Exactly one dimension changes; limit, company and optional fields survive untouched. */
export function clearCondition(filters:BrowseFilters,key:ConditionKey):BrowseFilters{return {...filters,[key]:defaults[key]};}
/** Duplicate IDs are invalid catalog input: retain the first record (including placeholders).
 * This matches nextInSequence's first-find behavior. Never merge names, scores or associations.
 * Only public name fields enter the existing name index; Work slots remain host-owned records.
 */
export function buildLibraryModel(catalog:CatalogView,filters:BrowseFilters,page=1,pageSize:PageSize=24):LibraryModel{
 const seen=new Set<string>();
 const works=catalog.works.filter(work=>{if(seen.has(work.id))return false;seen.add(work.id);return true;});
 const index=indexWorkNames(works,catalog.groups);
 const scope=matchingWorks(index,filters);
 const orderedWorks=sortWorks(scope.filter(work=>stageMatches(work,filters.stageFilter)),filters.sort);
 const pagination=paginate(orderedWorks.length,page,pageSize);
 const queue=Object.fromEntries(Object.keys(queueLabels).map(key=>[key,matchingWorks(index,{...filters,queue:key}).filter(work=>stageMatches(work,filters.stageFilter)).length]));
 const stage=Object.fromEntries(Object.keys(stageLabels).map(key=>[key,scope.filter(work=>stageMatches(work,key)).length]));
 const activeConditions:ActiveCondition[]=[];
 for(const key of Object.keys(defaults) as ConditionKey[]){
  const value=filters[key]??defaults[key];if(value===defaults[key])continue;
  const display=key==='group'?catalog.groups.find(group=>group.id===value)?.name??value:key==='queue'?queueLabels[value]??value:key==='stageFilter'?stageLabels[value]??value:key==='watch'?watchLabels[value]??value:key==='sort'?sortLabels[value]??value:value;
  activeConditions.push({key,value,label:`${labels[key]}：${display}`});
 }
 return {orderedWorks,orderedIds:orderedWorks.map(work=>work.id),rows:orderedWorks.slice((pagination.page-1)*pagination.pageSize,pagination.end),pagination,facetCounts:{queue,stage},activeConditions,watchableIds:orderedWorks.filter(work=>!!work.url).map(work=>work.id)};
}

import type {CatalogView,Work} from '../types';
import type {WatchSequence} from '../journey';
import {matchesWorkScope,nextInSequence} from '../watch-sequence';
import {stageMatches} from '../stage-display';
import type {SequenceModel,SequenceStatus} from './contract';
/** Keep the complete captured IDs and positions; never sort or silently repair a session. */
export function buildSequenceModel(sequence:WatchSequence,currentId:string,catalog:CatalogView):SequenceModel{
 const first=new Map<string,Work>();for(const work of catalog.works)if(!first.has(work.id))first.set(work.id,work);
 const linked=new Set(sequence.memberId?catalog.ratings.filter(rating=>rating.memberIds.includes(sequence.memberId!)).flatMap(rating=>rating.workIds):[]);
 const currentIndex=sequence.ids.indexOf(currentId);
 // The host's existing continuation oracle remains authoritative, including missing-current behavior.
 const nextId=nextInSequence(sequence,currentId,catalog)?.id??null;
 const nextIndex=nextId===null?-1:sequence.ids.indexOf(nextId,currentIndex+1);
 const rows=sequence.ids.map((id,index)=>{
  const work=first.get(id);let status:SequenceStatus='available';
  if(!work)status='missing';
  else if(work.placeholder||!work.url)status='unavailable';
  else if(!matchesWorkScope(work,sequence.filters,catalog.groups)||!stageMatches(work,sequence.filters.stageFilter))status='filtered';
  else if(sequence.memberId&&!linked.has(id))status='member-unlinked';
  return {id,position:index+1,name:work?.name??'已移除的作品',status,current:index===currentIndex,next:index===nextIndex};
 });
 return {rows,total:sequence.ids.length,currentPosition:currentIndex<0?null:currentIndex+1,nextId,continuableCount:currentIndex<0?0:rows.slice(currentIndex+1).filter(row=>row.status==='available').length,unrecoverable:currentIndex<0};
}

'use client';
import type {BrowseFilters} from '../../lib/idol/journey';
import {defaultFilters} from '../../lib/idol/journey';
import type {Group} from '../../lib/idol/types';
import type {LibraryModel,ConditionKey} from '../../lib/idol/library-browser/contract';
import {clearCondition} from '../../lib/idol/library-browser/query-model';
import {queueLabels} from '../../lib/idol/queues';
import './filters.css';
export function FilterControls({filters,onFiltersChange,groups,model,disabled=false,searchId='lb-search'}:{filters:BrowseFilters;onFiltersChange:(filters:BrowseFilters)=>void;groups:Group[];model:LibraryModel;disabled?:boolean;searchId?:string}){
 const change=(key:ConditionKey,value:string)=>{if(!disabled)onFiltersChange({...filters,[key]:value,limit:24});};
 const remove=(key:ConditionKey)=>{if(!disabled)onFiltersChange(clearCondition(filters,key));};
 return <section className="lb-filters" aria-label="作品筛选">
 <div className="lb-filter-fields">
 <label>公开名称搜索<input id={searchId} data-library-focus="search" value={filters.search} maxLength={1000} disabled={disabled} onChange={e=>change('search',e.target.value)} placeholder="歌曲、团体或视频标题"/></label>
 <label>团体<select value={filters.group} disabled={disabled} onChange={e=>change('group',e.target.value)}><option value="all">所有团体</option>{groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label>
 <label>代际<select value={filters.generation} disabled={disabled} onChange={e=>change('generation',e.target.value)}><option value="all">所有代际</option>{[...new Set(groups.map(g=>g.generation))].filter(Boolean).map(g=><option key={g}>{g}</option>)}</select></label>
 <label>观看队列<select value={filters.queue} disabled={disabled} onChange={e=>change('queue',e.target.value)}>{Object.entries(queueLabels).map(([key,label])=><option key={key} value={key}>{label}（{model.facetCounts.queue[key]??0}）</option>)}</select></label>
 <label>观看状态<select data-library-focus="watch" value={filters.watch??'all'} disabled={disabled} onChange={e=>change('watch',e.target.value)}>{[['all','所有观看状态'],['watched','已观看'],['unwatched','未观看'],['unmarked','未标记']].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>
 <label>作品排序<select data-library-focus="sort" value={filters.sort??'default'} disabled={disabled} onChange={e=>change('sort',e.target.value)}>{[['default','默认排序'],['release-desc','发行新到旧'],['release-asc','发行旧到新'],['score-desc','MV 分高到低']].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>
 </div>
 <div className="lb-stage-options" role="group" aria-label="舞台分类">{[['all','全部'],['ready','有舞台'],['alternative','其他现场'],['pending','暂无舞台']].map(([value,label])=><button type="button" key={value} disabled={disabled} aria-pressed={filters.stageFilter===value} onClick={()=>change('stageFilter',value)}>{label}（{model.facetCounts.stage[value]??0}）</button>)}</div>
 {model.activeConditions.length>0&&<div className="lb-active-conditions" aria-label="当前条件">{model.activeConditions.map(c=><button type="button" key={c.key} disabled={disabled} aria-label={`撤销${c.label}`} onClick={()=>remove(c.key)}>{c.label} ×</button>)}<button type="button" disabled={disabled} onClick={()=>{if(!disabled)onFiltersChange({...filters,...defaultFilters()});}}>重置全部条件</button></div>}
 {model.pagination.total===0&&model.activeConditions.length>0&&<p className="lb-empty-reason">当前条件组合没有匹配作品。可逐项撤销上方条件，其余条件会保留。{filters.queue==='unrated'?'“看过待评分”仅包含已观看且 MV 分数为空的作品；0 分表示已评分。':''}</p>}
 </section>;
}

export {LibraryBrowser} from './library-browser';
export type {LibraryBrowserProps} from './library-browser';
export {FilterControls} from './filter-controls';
export {ResultsView} from './results-view';
export {SequencePreview} from './sequence-preview';

'use client';
import {useMemo,useId} from 'react';
import type {BrowseFilters,WatchSequence} from '../../lib/idol/journey';
import type {CatalogView,Work} from '../../lib/idol/types';
import type {ReactNode} from 'react';
import type {PageSize,RestoreTarget,RestoreResolution} from '../../lib/idol/library-browser/contract';
import {paginate} from '../../lib/idol/library-browser/paging-model';
import {buildLibraryModel} from '../../lib/idol/library-browser/query-model';
import {makeWatchSequence} from '../../lib/idol/watch-sequence';
import {queueLabels} from '../../lib/idol/queues';
import {FilterControls} from './filter-controls';
import {ResultsView} from './results-view';
export type LibraryBrowserProps={catalog:CatalogView;filters:BrowseFilters;onFiltersChange:(filters:BrowseFilters)=>void;page:number;pageSize:PageSize;onPageChange:(page:number,pageSize:PageSize)=>void;renderWork:(work:Work,onOpen:()=>void)=>ReactNode;onOpenWork:(id:string,sequence:WatchSequence)=>void;restoreTarget?:RestoreTarget;restoreReady?:boolean;onRestoreReady?:(target:RestoreResolution)=>void;loading?:boolean;error?:string|null;readOnly?:boolean};
export function LibraryBrowser(props:LibraryBrowserProps){
 const {catalog,filters,page,pageSize}=props;
 // Navigation replaces BrowseFilters objects, so cache by query semantics rather than object identity.
 // Catalog identity remains a dependency: refreshed scores/relations/names must invalidate this cache.
 const {search,group,generation,queue,stageFilter,watch,sort}=filters;
 const queryModel=useMemo(()=>buildLibraryModel(catalog,{search,group,generation,queue,stageFilter,watch,sort,limit:24},1,24),[catalog,search,group,generation,queue,stageFilter,watch,sort]);
 const model=useMemo(()=>{const pagination=paginate(queryModel.orderedIds.length,page,pageSize);return {...queryModel,pagination,rows:queryModel.orderedWorks.slice((pagination.page-1)*pagination.pageSize,pagination.end)};},[queryModel,page,pageSize]);
 const sequence=useMemo(()=>makeWatchSequence(model.orderedWorks,queueLabels[filters.queue]??'作品库',filters),[model.orderedWorks,filters]);
 const searchId=useId();
 return <section className="lb-browser" aria-label="完整作品库" aria-busy={!!props.loading}>
 {props.readOnly&&<p className="lb-browser-readonly">只读浏览，不会修改评分、备注或观看状态。</p>}
 <FilterControls filters={filters} groups={catalog.groups} model={model} disabled={props.loading} searchId={searchId} onFiltersChange={next=>{props.onFiltersChange(next);props.onPageChange(1,pageSize);}}/>
 <ResultsView {...props} model={model} sequence={sequence} searchId={searchId}/>
 </section>;
}

'use client';

import {useEffect, useId, useLayoutEffect, useRef, useState} from 'react';
import type {FormEvent} from 'react';
import type {PageSize, ResultsViewProps} from '../../lib/idol/library-browser/contract';
import {paginate, resolveRestoreTarget} from '../../lib/idol/library-browser/paging-model';
import './results.css';

/** Controlled, bounded rendering. History and layout stabilization belong to the host. */
export function ResultsView({model, page, pageSize, onPageChange, renderWork, onOpenWork,
  sequence, restoreTarget, restoreReady = false, onRestoreReady, loading = false,
  error, searchId}: ResultsViewProps) {
  const paging = paginate(model.orderedWorks.length, page, pageSize);
  const rows = model.orderedWorks.slice((paging.page - 1) * paging.pageSize, paging.page * paging.pageSize);
  const uid = useId();
  const heading = useRef<HTMLHeadingElement>(null);
  const container = useRef<HTMLDivElement>(null);
  const pendingFocus = useRef<{page: number; size: PageSize} | null>(null);
  const completedRestore = useRef<string | null>(null);
  const requestedPage = useRef<string | null>(null);
  const [jump, setJump] = useState(String(paging.page));
  const [jumpError, setJumpError] = useState('');
  const restoreKey = restoreTarget ? JSON.stringify(restoreTarget) : null;

  useEffect(() => {setJump(String(paging.page)); setJumpError('');}, [paging.page, paging.pageSize]);
  useLayoutEffect(() => {
    if (restoreKey === null) {completedRestore.current = null; requestedPage.current = null;}
    if (!restoreTarget || loading || error) return;
    const resolution = resolveRestoreTarget(model.orderedIds, paging.pageSize, restoreTarget);
    const completionKey = `${restoreKey}:${JSON.stringify(resolution)}`;
    if (completionKey === completedRestore.current) return;
    if (paging.page !== resolution.page) {
      const request = `${restoreKey}:${resolution.page}:${paging.pageSize}`;
      if (requestedPage.current !== request) {
        requestedPage.current = request;
        onPageChange(resolution.page, paging.pageSize);
      }
      return;
    }
    // Never restore focus/geometry while the host is waiting for images or fonts.
    if (!restoreReady) return;
    const anchor = resolution.anchorId
      ? Array.from(container.current?.querySelectorAll<HTMLElement>('[data-lb-work-id]') ?? [])
        .find(element => element.dataset.lbWorkId === resolution.anchorId)
      : undefined;
    if (resolution.focus === 'anchor' && !anchor) return;
    const requestedFocus = restoreTarget.focusId ? document.getElementById(restoreTarget.focusId) : null;
    const focus = resolution.focus === 'anchor'
      ? (requestedFocus && anchor?.contains(requestedFocus) ? requestedFocus
        : anchor?.querySelector<HTMLElement>('button:not([disabled]), a[href], [tabindex="0"]') ?? anchor)
      : ((searchId ? document.getElementById(searchId) : null) ?? heading.current);
    focus?.focus({preventScroll: true});
    completedRestore.current = completionKey;
    requestedPage.current = null;
    pendingFocus.current = null;
    onRestoreReady?.(resolution);
  }, [restoreKey, restoreTarget, restoreReady, model.orderedIds, paging.page, paging.pageSize,
    loading, error, onPageChange, onRestoreReady, searchId]);

  useLayoutEffect(() => {
    const pending = pendingFocus.current;
    if (!pending || loading || error || pending.page !== paging.page || pending.size !== paging.pageSize) return;
    // Focus only after an explicit paging gesture, never on ordinary mount/refresh.
    pendingFocus.current = null;
    heading.current?.focus();
  }, [paging.page, paging.pageSize, loading, error]);

  function changePage(next: number, size: PageSize = paging.pageSize) {
    if (loading || error) return;
    const nextPage = paginate(model.orderedWorks.length, next, size).page;
    if (nextPage === paging.page && size === paging.pageSize) return;
    pendingFocus.current = {page: nextPage, size};
    onPageChange(nextPage, size);
  }
  function submitJump(event: FormEvent) {
    event.preventDefault();
    if (loading || error) return;
    const value = jump.trim();
    if (!/^\d+$/.test(value) || !Number.isSafeInteger(Number(value)) || Number(value) < 1 || Number(value) > paging.pageCount) {
      setJumpError(`请输入 1 至 ${paging.pageCount} 的整数页码。`);
      return;
    }
    setJumpError('');
    changePage(Number(value));
  }

  return <section className="lb-results" aria-busy={loading} aria-labelledby={`${uid}-title`}>
    <h2 id={`${uid}-title`} className="lb-results-heading" tabIndex={-1} ref={heading}>作品浏览</h2>
    <p className="lb-results-summary" role="status" aria-live="polite" aria-atomic="true">
      {loading ? '正在加载作品…' : error ? '作品暂时无法显示。' : paging.total
        ? `第 ${paging.start}–${paging.end} 项，共 ${paging.total} 项；第 ${paging.page} / ${paging.pageCount} 页`
        : '共 0 项作品'}
    </p>
    {error ? <p role="alert" className="lb-results-error">{error}</p> : null}
    {!loading && !error && !paging.total ? <p className="lb-results-empty">{model.activeConditions.length
      ? '没有符合当前条件的作品，请撤销上方条件后重试。' : '作品库暂无作品。'}</p> : null}
    <div ref={container} className="lb-results-grid" data-lb-results-grid="" aria-label="本页作品">
      {!loading && !error && rows.map(work => <div key={work.id} className="lb-results-card" data-lb-work-id={work.id}
        tabIndex={-1} aria-label={work.name}>
        {renderWork(work, () => {
          if (loading || error) return;
          // Safari/touch and programmatic clicks do not necessarily focus buttons.
          // Capture the actual opened card before the host snapshots its history anchor.
          const card = Array.from(container.current?.querySelectorAll<HTMLElement>('[data-lb-work-id]') ?? [])
            .find(element => element.dataset.lbWorkId === work.id);
          (card?.querySelector<HTMLElement>('button:not([disabled]), a[href], [tabindex="0"]') ?? card)?.focus({preventScroll:true});
          onOpenWork(work.id, sequence);
        })}
      </div>)}
    </div>
    <nav className="lb-results-paging" aria-label="作品分页">
      <button type="button" disabled={loading || !!error || paging.page <= 1} onClick={() => changePage(paging.page - 1)}>上一页</button>
      <span aria-current="page">第 {paging.page} / {paging.pageCount} 页</span>
      <button type="button" disabled={loading || !!error || paging.page >= paging.pageCount} onClick={() => changePage(paging.page + 1)}>下一页</button>
      <label htmlFor={`${uid}-size`}>每页</label>
      <select id={`${uid}-size`} value={paging.pageSize} disabled={loading || !!error}
        onChange={event => {const size = Number(event.target.value); if (size === 24 || size === 48) changePage(1, size);}}>
        <option value={24}>24 项</option><option value={48}>48 项</option>
      </select>
      <form className="lb-results-jump" onSubmit={submitJump} noValidate>
        <label htmlFor={`${uid}-jump`}>跳至页码</label>
        <input id={`${uid}-jump`} type="text" inputMode="numeric" value={jump} disabled={loading || !!error || !paging.total}
          aria-invalid={!!jumpError} aria-describedby={jumpError ? `${uid}-jump-error` : undefined}
          onChange={event => {setJump(event.target.value); setJumpError('');}} />
        <button type="submit" disabled={loading || !!error || !paging.total}>前往</button>
      </form>
    </nav>
    {jumpError ? <p id={`${uid}-jump-error`} className="lb-results-error" role="alert">{jumpError}</p> : null}
  </section>;
}

.lb-results{min-width:0;max-width:100%;color:inherit}
.lb-results-heading{font-size:1.2rem;margin-block:1rem .5rem}
.lb-results-summary{font-variant-numeric:tabular-nums}
.lb-results-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:1rem}
.lb-results-card{min-width:0;overflow-wrap:anywhere}
.lb-results-card img{max-width:100%}
.lb-results-paging,.lb-results-jump{display:flex;align-items:center;flex-wrap:wrap;gap:.6rem}
.lb-results-paging{margin-block:1rem}
.lb-results-paging button,.lb-results-paging select,.lb-results-jump input{min-height:44px;max-width:100%;font:inherit;padding:.45rem .65rem}
.lb-results-jump input{width:5rem;box-sizing:border-box}
.lb-results-error{color:#a82020;overflow-wrap:anywhere}
.lb-results-empty{padding:1rem;border:1px solid currentColor;border-radius:.5rem}
.lb-results :focus-visible{outline:3px solid #346de0;outline-offset:3px}
.lb-results button:disabled{opacity:.55;cursor:not-allowed}
@media(prefers-reduced-motion:reduce){.lb-results *{scroll-behavior:auto;animation:none;transition:none}}

'use client';

import {useId, useLayoutEffect, useRef, useState} from 'react';
import type {PageSize, SequencePreviewProps, SequenceStatus} from '../../lib/idol/library-browser/contract';
import {paginate} from '../../lib/idol/library-browser/paging-model';
import {buildSequenceModel} from '../../lib/idol/library-browser/sequence-model';
import './sequence.css';

const statusLabels: Record<SequenceStatus, string> = {
  available: '可观看', missing: '已删除或不存在', unavailable: '来源不可用',
  filtered: '已不符合本次条件', 'member-unlinked': '成员关联已断开',
};

/** Read-only original session order; only the host may navigate through onNext. */
export function SequencePreview({sequence, currentId, catalog, onNext, nextDisabled = false}: SequencePreviewProps) {
  const model = buildSequenceModel(sequence, currentId, catalog);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<PageSize>(24);
  const paging = paginate(model.total, page, pageSize);
  const rows = model.rows.slice((paging.page - 1) * paging.pageSize, paging.page * paging.pageSize);
  const uid = useId();
  const summary = useRef<HTMLParagraphElement>(null);
  const deliberate = useRef(false);
  useLayoutEffect(() => {
    if (!deliberate.current) return;
    deliberate.current = false;
    summary.current?.focus();
  }, [paging.page, paging.pageSize]);
  const disabled = nextDisabled || !onNext || !model.nextId || model.unrecoverable;

  return <details className="lb-sequence">
    <summary className="lb-sequence-toggle">本次观看列表（{model.total} 项）</summary>
    <div className="lb-sequence-panel">
      <p className="lb-sequence-label">{sequence.label} · 只读预览</p>
      <p>{model.unrecoverable ? '当前作品不在原会话中，无法恢复会话位置。'
        : model.currentPosition === null ? '当前没有可恢复的作品位置。'
          : `原会话第 ${model.currentPosition} / ${model.total} 项`}</p>
      <p>当前可继续 {model.continuableCount} 项；原顺序与总数保持不变。</p>
      <p ref={summary} tabIndex={-1} className="lb-sequence-page-status" role="status" aria-live="polite" aria-atomic="true">
        {model.total ? `预览第 ${paging.start}–${paging.end} 项，第 ${paging.page} / ${paging.pageCount} 页` : '本次观看列表为空。'}
      </p>
      <ol className="lb-sequence-list" start={(paging.page - 1) * paging.pageSize + 1} aria-label="原会话顺序">
        {rows.map((row, index) => <li key={`${row.id}:${row.position}:${index}`} className="lb-sequence-row"
          data-lb-sequence-id={row.id} aria-current={row.current ? 'step' : undefined}>
          <span className="lb-sequence-name">{row.name}</span>
          <span className="lb-sequence-state">{row.current ? '当前作品 · ' : ''}{row.next ? '下一支 · ' : ''}{statusLabels[row.status]}</span>
        </li>)}
      </ol>
      <nav className="lb-sequence-paging" aria-label="观看列表预览分页">
        <button type="button" disabled={paging.page <= 1} onClick={() => {
          if (paging.page <= 1) return; deliberate.current = true; setPage(paging.page - 1);
        }}>预览上一页</button>
        <span aria-current="page">第 {paging.page} / {paging.pageCount} 页</span>
        <button type="button" disabled={paging.page >= paging.pageCount} onClick={() => {
          if (paging.page >= paging.pageCount) return; deliberate.current = true; setPage(paging.page + 1);
        }}>预览下一页</button>
        <label htmlFor={`${uid}-size`}>预览每页</label>
        <select id={`${uid}-size`} value={pageSize} onChange={event => {
          const size = Number(event.target.value);
          if (size !== 24 && size !== 48) return;
          deliberate.current = true; setPage(1); setPageSize(size);
        }}><option value={24}>24 项</option><option value={48}>48 项</option></select>
      </nav>
      {!model.nextId && !model.unrecoverable ? <p className="lb-sequence-end" role="status">本次观看已到末尾，没有可继续的下一支。</p> : null}
      {onNext ? <button className="lb-sequence-next" type="button" disabled={disabled}
        onClick={() => {if (!disabled) onNext();}}>下一支</button> : null}
    </div>
  </details>;
}

.lb-sequence{max-width:100%;min-width:0;border:1px solid #8a8a8a;border-radius:.6rem;margin-block:1rem}
.lb-sequence-toggle{cursor:pointer;padding:.8rem;min-height:44px;box-sizing:border-box}
.lb-sequence-panel{padding:0 1rem 1rem;overflow-wrap:anywhere}
.lb-sequence-label{font-weight:600}
.lb-sequence-list{padding-inline-start:2.5rem}
.lb-sequence-row{padding:.5rem .25rem;border-block-end:1px solid #aaa6}
.lb-sequence-row[aria-current="step"]{font-weight:700;background:#7771}
.lb-sequence-name,.lb-sequence-state{display:block;overflow-wrap:anywhere}
.lb-sequence-state{font-size:.875rem}
.lb-sequence-paging{display:flex;align-items:center;flex-wrap:wrap;gap:.6rem}
.lb-sequence button,.lb-sequence select{min-height:44px;max-width:100%;font:inherit;padding:.45rem .65rem}
.lb-sequence-next{margin-block-start:.75rem}
.lb-sequence :focus-visible{outline:3px solid #346de0;outline-offset:3px}
.lb-sequence button:disabled{opacity:.55;cursor:not-allowed}
@media(prefers-reduced-motion:reduce){.lb-sequence *{scroll-behavior:auto;animation:none;transition:none}}

