test('actual proposed hook keeps restored page in React entry and history after takeover/rerender',()=>{const h=harness();assert.equal(h.api.displayReady,false);h.api.libraryRestoreMounted({page:3,anchorId:'recW51',offset:100,focus:'anchor',reason:'anchor'});h.flush();assert.equal(h.api.displayReady,true);assert.equal(h.api.filters.page,3);assert.equal(h.history.state.idolBrowse.lists.works.page,3);h.userScroll(600);h.api.updateFilters({limit:96});h.flush();assert.equal(h.api.libraryRestoreTarget,undefined);assert.equal(h.api.filters.page,3);assert.equal(h.api.filters.limit,96);});
test('actual hook page/size survives detail, next, Back and Forward with original full sequence',()=>{const h=harness();h.api.libraryRestoreMounted({page:1,anchorId:null,offset:0,focus:'search',reason:'page'});h.flush();h.api.setLibraryPage(3,48);const sequence={ids:['recA','recB','recC'],label:'synthetic',filters:pure.defaultFilters()};assert.equal(h.api.navigate({work:'recA'},'作品库',undefined,sequence),true);h.flush();assert.equal(h.api.continueWork('recB'),true);h.flush();h.api.back({nav:'works',work:null,member:null,video:'mv'});h.flush();assert.equal(h.api.filters.page,3);assert.equal(h.api.filters.pageSize,48);assert.equal(h.api.displayReady,false);h.api.libraryRestoreMounted({page:3,anchorId:null,offset:0,focus:'search',reason:'page'});h.flush();assert.equal(h.api.displayReady,true);h.history.go(1);h.flush();assert.equal(h.api.route.work,'recA');assert.deepEqual(Array.from(h.api.sequence.ids),['recA','recB','recC']);});
test('actual hook still rejects dirty and pending navigation, preserving current route and preferences',()=>{const h=harness();h.api.libraryRestoreMounted({page:1,anchorId:null,offset:0,focus:'search',reason:'page'});h.flush();h.api.setLibraryPage(3,24);const sequence={ids:['recA','recB'],label:'synthetic',filters:pure.defaultFilters()};h.api.navigate({work:'recA'},'作品库',undefined,sequence);h.flush();h.setDirty(true,false);assert.equal(h.api.continueWork('recB'),false);assert.equal(h.api.route.work,'recA');h.setDirty(false);h.setBlocked(true);assert.equal(h.api.continueWork('recB'),false);assert.equal(h.api.route.work,'recA');assert.equal(h.api.filters.page,3);});
test('proposed readEntry accepts legacy limit and valid navigation paging but rejects malformed values',()=>{const entry=pure.newEntry('/?view=works');entry.lists.works.limit=96;assert.ok(pure.readEntry({idolBrowse:entry},'/?view=works'));for(const [page,pageSize,valid] of [[3,48,true],[0,24,false],[1,25,false],[1.2,24,false],[10001,24,false]]){const next=structuredClone(entry);Object.assign(next.lists.works,{page,pageSize});assert.equal(!!pure.readEntry({idolBrowse:next},'/?view=works'),valid);}});
